(()=>{const b=document.querySelector('#lang');if(!b)return;const paint=()=>{const pl=b.textContent.includes('PL');b.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/></svg><span class="lang-code">'+(pl?'PL':'EN')+'</span><span class="chevron">⌄</span>';b.setAttribute('aria-label',pl?'Zmień język':'Change language')};new MutationObserver(paint).observe(b,{childList:true,subtree:true});paint()})();
